import { z } from 'zod'

import { qrTokenSchema } from './object.js'

/**
 * Public report form API schemas (`specs/06-report-form.md` §7.3, WP-M2-04b).
 *
 * The endpoint is unauthenticated, so every rule of §7.3.1 lives here and the API
 * answers only error **codes** — never translated text. `ticket_no` is generated by
 * the database (§4.11), `status_token` with the ticket (§7.3.4), and `photos` are
 * the base64 data URLs of §7.4 whose bytes the service verifies.
 */

const trimmedText = (max: number) =>
  z
    .string()
    .trim()
    .max(max)
    .optional()
    .transform((value) => (value === '' ? undefined : value))

/** `text_templates.key` values — machine keys, never translated text (plan §3). */
export const faultTemplateKeySchema = z.string().regex(/^[a-z0-9_.]{1,64}$/)

export const publicReportContactSchema = z.object({
  name: trimmedText(120),
  phone: trimmedText(60),
  email: trimmedText(320).pipe(z.email().optional()),
})

/**
 * One photo as a data URL (`specs/06-report-form.md` §7.4, WP-M2-04c): the canvas
 * output of the client compressor travels inside the same JSON body. Only
 * `image/jpeg` and `image/png` are claimed here — the server still verifies the
 * magic bytes, and the array bound of the request schema is structural only, so
 * the service can answer `422 photo_limit_exceeded` instead of a body-limit `413`.
 */
export const photoDataUrlSchema = z
  .string()
  .regex(/^data:image\/(jpeg|png);base64,[A-Za-z0-9+/]+={0,2}$/)

export const publicReportRequestSchema = z.object({
  qrToken: qrTokenSchema,
  clientUuid: z.uuid(),
  text: trimmedText(4000),
  faultTemplateKeys: z
    .array(faultTemplateKeySchema)
    .max(9)
    .default([])
    .refine((keys) => new Set(keys).size === keys.length),
  systemId: z.uuid().optional(),
  contact: publicReportContactSchema.default({
    name: undefined,
    phone: undefined,
    email: undefined,
  }),
  /** Device capture time with offset; the server decides about the clock rule. */
  reportedAt: z.iso.datetime({ offset: true, local: true }).optional(),
  locale: z.enum(['de', 'en']).default('de'),
  /** Structural bound of 12; the semantic limit of 6 lives in the service (§7.4). */
  photos: z.array(photoDataUrlSchema).max(12).default([]),
})

export const publicReportResponseSchema = z.object({
  ticketId: z.uuid(),
  ticketNo: z.string(),
  status: z.literal('NEW'),
  statusToken: qrTokenSchema,
  reportedAt: z.iso.datetime(),
  receivedAt: z.iso.datetime(),
  deadlineAt: z.iso.datetime(),
  clockSkewed: z.boolean(),
  photoCount: z.number().int().min(0),
})

export type PublicReportContact = z.infer<typeof publicReportContactSchema>
export type PublicReportRequest = z.infer<typeof publicReportRequestSchema>
export type PublicReport = z.infer<typeof publicReportResponseSchema>
